var t = new Temperature(20);
Console.WriteLine($"{t} is {t.Fahrenheit} °F");
try
{
    t.Celsius = -300;
}
catch (ArgumentOutOfRangeException)
{
    Console.WriteLine("Cannot go below absolute zero (-273.15 °C)");
}

class Temperature
{
    public Temperature(double celsius) { }

    // TODO: check the value in the setter, and give Fahrenheit a setter too
    public double Celsius { get; set; }
    public double Fahrenheit => 0;
}
